using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Web.Script.Serialization;

internal static class EnemyHealthVerification {
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static void Var(List<byte> b,uint value){do{byte n=(byte)(value&127);value>>=7;b.Add((byte)(n|(value!=0?128:0)));}while(value!=0);}
    static byte[] Spawn(uint actor,uint current=119700,uint maximum=119700,uint npc=2100752){var b=new List<byte>{0x41,0x36};Var(b,actor);b.AddRange(new byte[3]);b.AddRange(BitConverter.GetBytes(npc));b.AddRange(new byte[21]);Var(b,current);Var(b,maximum);b.AddRange(new byte[52]);return b.ToArray();}
    static byte[] Energy(uint actor){var b=new List<byte>{0,0x8d};Var(b,actor);b.AddRange(new byte[]{1,1,3});b.AddRange(BitConverter.GetBytes(139100u));return b.ToArray();}
    static byte[] Hp(uint actor,uint current){var b=new List<byte>{0,0x8d};Var(b,actor);b.AddRange(new byte[]{2,1,0});b.AddRange(BitConverter.GetBytes((long)current));return b.ToArray();}
    static byte[] Select(uint actor){var b=new List<byte>{0x34,0x38,0,0,0};Var(b,actor);return b.ToArray();}
    static byte[] Aim(uint actor,uint target,uint skill){var b=new List<byte>{2,0x38};Var(b,actor);b.Add(0);b.AddRange(BitConverter.GetBytes(skill));b.AddRange(new byte[]{0,2});Var(b,target);b.AddRange(BitConverter.GetBytes(0f));b.AddRange(BitConverter.GetBytes(93348f));b.AddRange(BitConverter.GetBytes(26545f));b.AddRange(BitConverter.GetBytes(26728f));return b.ToArray();}
    static void Feed(EnemyHealthSignal signal,byte[] b,double time,string flow="A"){signal.Consume(b,0,b.Length,time,flow);}
    static byte[] Map(uint map){var b=new byte[48];b[0]=0x21;b[1]=0x36;Buffer.BlockCopy(BitConverter.GetBytes(map),0,b,6,4);return b;}
    static byte[] Remove(uint actor){var b=new List<byte>{0x42,0x36};Var(b,actor);b.AddRange(new byte[2]);return b.ToArray();}
    static byte[] Focus(uint actor,uint target){var b=new List<byte>{0x35,0x38};Var(b,actor);b.Add(0);Var(b,target);return b.ToArray();}
    static byte[] PartyHealth(uint actor,uint hp,uint max){var b=new List<byte>{0x1b,0x92};Var(b,actor);Var(b,hp);Var(b,max);b.AddRange(BitConverter.GetBytes(100u));b.AddRange(BitConverter.GetBytes(100u));b.AddRange(new byte[17]);return b.ToArray();}
    static void VerifyPlayerTargets(){
        var signal=new EnemyHealthSignal();signal.Configure(true);double t=DpsHistory.UtcNow();
        var own=EnemyTargetVerification.Player(100,"LocalProbe",12000,14000,true);var rival=EnemyTargetVerification.Player(200,"RivalProbe",16000,18000,false);
        Feed(signal,Map(61),t);Feed(signal,own,t);Feed(signal,rival,t);Check(signal.Read()==null,"Seeing a remote character alone must not select a PvP target");
        Feed(signal,Select(200),t+1);var sample=signal.Read();Check(sample!=null&&sample.IsPlayer&&sample.Actor==200&&sample.Name=="RivalProbe"&&sample.Current==16000&&sample.Maximum==18000&&sample.Locked&&sample.Npc==0,"Hard selection displays remote player name and explicit current/max without an NPC ID");
        Check(!sample.BaseLevel.HasValue&&!sample.AdjustedLevel.HasValue&&EnemySpecies.Name(sample.Npc,"en")==null,"Remote player never inherits an NPC level adjustment or species");
        Check(sample.Position.Known&&sample.Position.X==93000,"Remote position comes from its validated profile state");
        Feed(signal,Hp(200,13000),t+2);Check(signal.Read().Current==13000&&signal.Read().Maximum==18000,"Remote current-only update retains received maximum");Feed(signal,Hp(200,2000),t+1);Check(signal.Read().Current==13000,"Older rival health cannot overwrite newer values");
        Feed(signal,PartyHealth(200,14000,19000),t+3);Check(signal.Read().Current==14000&&signal.Read().Maximum==19000,"Valid remote party health can update explicit maximum");
        Feed(signal,Select(100),t+4);Check(signal.Read()==null&&signal.Actor("A",100)==null,"Own player must never appear as our enemy bar");Feed(signal,Select(0),t+4);
        Feed(signal,Aim(100,200,15110340),t+5);Check(signal.Read()!=null&&signal.Read().Actor==200&&!signal.Read().Locked,"Own primary offensive aim can select an unlocked rival");
        Feed(signal,Spawn(300),t+5);Feed(signal,Aim(100,300,15780007),t+6);Check(signal.Read().Actor==200,"Proc aim does not replace the rival");
        Feed(signal,Select(300),t+7);Check(!signal.Read().IsPlayer&&signal.Read().Npc==2100752&&signal.Read().Name==null,"Selecting an NPC after a player preserves original NPC metadata");
        Feed(signal,Select(0),t+7);Feed(signal,rival,t+8,"B");Feed(signal,Select(200),t+8,"B");Check(signal.Read()==null,"Another flow cannot select our remote player");Feed(signal,Aim(100,200,15110340),t+8);Check(signal.Read().Name=="RivalProbe","Player profiles stay scoped to their flow");
        Feed(signal,Hp(200,0),t+9);Check(signal.Read()==null,"Rival death clears selection instead of showing an earlier soft target");Feed(signal,Hp(200,17000),t+10);Check(signal.Read()==null,"A health update alone does not select a resurrected rival");Feed(signal,Select(200),t+10);Check(signal.Read().Current==17000,"Explicit reselect after revival reads new health");
        Feed(signal,Remove(200),t+11);Check(signal.Read()==null&&signal.Actor("A",200)==null,"Player removal clears both profile and selection");
        var bad=EnemyTargetVerification.Player(201,"InvalidProbe",19000,18000,false);Feed(signal,bad,t+11);Feed(signal,Hp(201,10000),t+12);Feed(signal,Select(201),t+12);Check(signal.Read()==null,"Health updates cannot invent a missing or malformed player profile");
        Feed(signal,rival,t+13);Feed(signal,Select(200),t+13);var targets=new EnemyTargetSignal();targets.Configure(true);targets.Consume(own,0,own.Length,t+13,"A");targets.Consume(rival,0,rival.Length,t+13,"A");Check(targets.Read(signal.Read(),signal)==null,"Our rival selection is not evidence of the rival's own target");
        var focus=Focus(200,100);targets.Consume(focus,0,focus.Length,t+14,"A");var target=targets.Read(signal.Read(),signal);Check(target!=null&&target.Actor==100&&target.Name=="LocalProbe"&&target.Current==12000&&target.IsSelf&&target.IsPlayer,"Received PvP rival focus selects our confirmed character health");
        focus=Focus(200,300);targets.Consume(focus,0,focus.Length,t+15,"A");Check(targets.Read(signal.Read(),signal).Npc==2100752,"Rival focus can point to a confirmed NPC or summon");focus=Focus(200,0);targets.Consume(focus,0,focus.Length,t+16,"A");Check(targets.Read(signal.Read(),signal)==null,"Received PvP focus clear hides target-of-target");
        Feed(signal,Map(20),t+17);Check(signal.Read()==null&&signal.Actor("A",200)==null,"Abyss map transition cannot reuse a previous arena rival");Feed(signal,own,t+18);Feed(signal,Select(200),t+18);Check(signal.Read()==null,"Returning own identity does not resurrect stale remote profiles");Feed(signal,rival,t+18);Check(signal.Read()!=null&&signal.Read().IsPlayer,"New received remote profile supports the same selection path on Abyss map20");
        signal.Reset();Check(signal.Read()==null,"Reset clears player target state");signal.Configure(false);Feed(signal,own,t+19);Feed(signal,rival,t+19);Feed(signal,Select(200),t+19);Check(signal.Read()==null,"Disabled enemy bar ignores player profiles and selection");
    }
    static byte[] WithFaction(byte[] profile,string name,bool own,int faction){var n=System.Text.Encoding.UTF8.GetBytes(name);for(int i=2;i<=profile.Length-n.Length;i++){bool equal=true;for(int k=0;k<n.Length;k++)if(profile[i+k]!=n[k]){equal=false;break;}if(equal){profile[i+n.Length+(own?2:0)+4]=(byte)faction;return profile;}}throw new Exception("Faction fixture name missing");}
    static byte[] ArenaRoster(string own,string rival,int faction=1,uint content=11){var b=new List<byte>{0x19,0xe3};Var(b,2001);b.AddRange(BitConverter.GetBytes(1u));b.AddRange(BitConverter.GetBytes((ulong)content));b.AddRange(BitConverter.GetBytes(7u));b.Add(2);for(int team=1;team<=2;team++){string name=team==1?rival:own;int server=team==1&&faction==2?2301:1301;int side=team==1?faction:1;b.Add((byte)team);b.AddRange(BitConverter.GetBytes(1500UL));b.AddRange(BitConverter.GetBytes(1500u));b.Add(1);b.AddRange(new byte[8]);b.AddRange(BitConverter.GetBytes(((ulong)server<<48)|(uint)(1234+team)));var n=System.Text.Encoding.UTF8.GetBytes(name);b.Add((byte)n.Length);b.AddRange(n);b.AddRange(BitConverter.GetBytes(26u));b.Add((byte)side);b.AddRange(BitConverter.GetBytes(45u));b.AddRange(new byte[4]);var tail=new byte[27];Buffer.BlockCopy(BitConverter.GetBytes((ushort)server),0,tail,0,2);tail[10]=1;b.AddRange(tail);}return b.ToArray();}
    static void VerifyTargetRelations(){
        TargetRelations.Arena roster;var frame=ArenaRoster("LocalProbe","RivalProbe");Check(TargetRelations.ParseArena(frame,0,frame.Length,out roster),"Complete recorded-shaped1v1 roster has two distinct teams");for(int end=0;end<frame.Length;end++)Check(!TargetRelations.ParseArena(frame,0,end,out roster),"Truncated arena roster cannot classify a player");var extra=new byte[frame.Length+1];Buffer.BlockCopy(frame,0,extra,0,frame.Length);Check(!TargetRelations.ParseArena(extra,0,extra.Length,out roster),"Unsupported roster tail must remain unknown");Check(!TargetRelations.ParseArena(ArenaRoster("SameName","SameName"),0,ArenaRoster("SameName","SameName").Length,out roster),"Duplicate participant names cannot be matched ambiguously");
        var signal=new EnemyHealthSignal();signal.Configure(true);double t=DpsHistory.UtcNow();var own=EnemyTargetVerification.Player(100,"LocalProbe",12000,14000,true);var rival=EnemyTargetVerification.Player(200,"RivalProbe",16000,18000,false);
        // Deliberately use the disproved candidate2 for a neutral. Only the
        // separately announced faction may classify a world-map selection.
        EnemyTargetSignal.Player meta;Check(EnemyTargetSignal.PlayerState(rival,0,rival.Length,false,out meta),"Faction test profile valid");rival[meta.StateOffset-1]=2;
        Feed(signal,Map(1010),t);Feed(signal,own,t);Feed(signal,rival,t);Feed(signal,Select(200),t);Check(signal.Read().ColorKind==2&&signal.Read().RelationshipSource=="Faction"&&signal.Read().RelationCandidate==2,"Neutral player with rejectedcandidate2 uses faction, never the guessed relation byte");
        Feed(signal,Map(60),t+1);Feed(signal,own,t+1);Feed(signal,rival,t+1);Feed(signal,Select(200),t+1);Check(signal.Read().ColorKind==-1,"Arena must not infer neutrality from a shared faction without teams");Feed(signal,frame,t+2);Check(signal.Read().ColorKind==1&&signal.Read().RelationshipSource=="Arena teams","Received opposing teams override same-faction arena rival");
        var invalid=(byte[])frame.Clone();invalid[invalid.Length-1]=1;Feed(signal,invalid,t+3);Check(signal.Read().ColorKind==-1,"Invalid replacement roster clears classification");Feed(signal,frame,t+3);Feed(signal,Map(61),t+4);Feed(signal,own,t+4);Feed(signal,rival,t+4);Feed(signal,Select(200),t+4);Check(signal.Read().ColorKind==-1,"A roster for the other arena cannot leak across map");var other=ArenaRoster("LocalProbe","RivalProbe",1,22);Feed(signal,other,t+5);Check(signal.Read().ColorKind==1,"Second observed arena layout uses its matching roster");
        Feed(signal,Map(20),t+6);Feed(signal,own,t+6);Feed(signal,rival,t+6);Feed(signal,Select(200),t+6);Check(signal.Read().ColorKind==2,"Abyss same-faction player uses neutral palette without old arena teams");rival=WithFaction(rival,"RivalProbe",false,2);Feed(signal,rival,t+7);Check(signal.Read().ColorKind==1&&signal.Read().Faction==2&&signal.Read().RelationshipSource=="Faction","Abyss opposite faction uses enemy player palette");
        Feed(signal,Map(200003),t+8);Feed(signal,own,t+8);Feed(signal,rival,t+8);Feed(signal,Select(200),t+8);Check(signal.Read().ColorKind==-1,"Unvalidated modes retain base colors");
        var rng=new Random(403);for(int n=0;n<1500;n++){var random=new byte[rng.Next(2,600)];rng.NextBytes(random);random[0]=0x19;random[1]=0xe3;Check(!TargetRelations.ParseArena(random,0,random.Length,out roster),"Random arena bytes cannot supply valid teams");}
    }
    static void VerifyCacheIsolation(){
        var signal=new EnemyHealthSignal();signal.Configure(true);double t=DpsHistory.UtcNow();Feed(signal,Map(1010),t);Feed(signal,Energy(1923),t);Feed(signal,Spawn(23556,26600,26600,2989661),t);Feed(signal,Spawn(23557),t);
        for(uint i=0;i<900;i++)Feed(signal,EnemyTargetVerification.Player(10000+i,"Crowd"+i,8000,9000,false),t+1+i*.001);
        Feed(signal,Select(23556),t+3);Check(signal.Read()!=null&&signal.Read().Actor==23556&&signal.Read().Current==26600,"Player population cannot evict a stationary unselected NPC profile");Check(signal.Read().ColorKind==3&&signal.Read().RelationshipSource=="Confirmed neutral NPC catalogue","Confirmed NPC template uses fourth palette on its observed map");
        Feed(signal,Select(0),t+3);for(int n=0;n<40;n++){Feed(signal,EnemyTargetVerification.Player(10899,"Crowd899",8000,9000,false),t+4+n*.001);Feed(signal,Spawn(23556,26000,26600,2989661),t+4+n*.001);}
        Check(signal.Actor("A",23556)!=null&&signal.Actor("A",23557)!=null,"Refreshing existing records at capacity cannot discard another NPC");
        for(uint i=0;i<510;i++)Feed(signal,Spawn(50000+i),t+5+i*.001);Feed(signal,Select(23556),t+6);Feed(signal,Spawn(99999),t+6);Check(signal.Read()!=null&&signal.Read().Actor==23556,"NPC quota retains the selected NPC");
        var json=new JavaScriptSerializer();var cache=json.Deserialize<Dictionary<string,object>>(json.Serialize(signal.CacheStatus));Check(Convert.ToInt32(cache["npcProfiles"])==512&&Convert.ToInt32(cache["playerProfiles"])==512,"Independent quotas remain bounded with full NPC and player populations");Feed(signal,EnemyTargetVerification.Player(99999,"Replacement",8000,9000,false),t+7);cache=json.Deserialize<Dictionary<string,object>>(json.Serialize(signal.CacheStatus));Check(Convert.ToInt32(cache["npcProfiles"])==511&&Convert.ToInt32(cache["playerProfiles"])==512,"Actor type replacement respects the incoming type quota");
        Check(NeutralNpcCatalogue.Known(2930066,1010)&&NeutralNpcCatalogue.Known(2939438,1010)&&!NeutralNpcCatalogue.Known(2930066,20)&&!NeutralNpcCatalogue.Known(2100752,1010),"Neutral NPC classification is exact confirmed template/map metadata, never a prefix or display-name guess");
        signal.Reset();Check(signal.Read()==null,"Transport reset clears both independent populations");
    }
    static void VerifyTargetPalettes(string root){
        var original=new EnemyHealthOptions();original.Bounds=new Rectangle(230,180,480,7);original.Name.FontSize=23;original.Name.OffsetX=35;original.Name.OffsetY=70;original.Bar.CurrentOffsetY=44;original.Bar.MediumColor="#AC1234";original.Name.Color="#CDEF12";original.Bar.TextColor="#EBEBEB";
        var json=new JavaScriptSerializer();var legacy=EnemyHealthOptions.Read(json.Deserialize<Dictionary<string,object>>(json.Serialize(new{enemyHealth=original})));Check(legacy.Bounds==original.Bounds&&legacy.Name.FontSize==23&&legacy.Bar.MediumColor=="#AC1234"&&legacy.Name.Color=="#CDEF12","Existing target layout and colors survive new palette migration");
        for(int kind=0;kind<4;kind++){var paint=legacy.ForPalette(kind);Check(paint.Bounds==original.Bounds&&paint.Name.FontSize==23&&paint.Name.OffsetX==35&&paint.Name.OffsetY==70&&paint.Bar.CurrentOffsetY==44,"Every target preset uses the same geometry and typography");}
        var enemy=legacy.Colors(1);enemy.Medium="#EE1122";enemy.Name="#DD2233";legacy.StoreColors(1,enemy);var neutral=legacy.Colors(2);neutral.Medium="#22CC88";neutral.Value="#12ABCD";legacy.StoreColors(2,neutral);var neutralNpc=legacy.Colors(3);neutralNpc.Medium="#7799DD";legacy.StoreColors(3,neutralNpc);Check(legacy.Bar.MediumColor=="#AC1234"&&legacy.Colors(1).Medium=="#EE1122"&&legacy.Colors(2).Medium=="#22CC88","Independent enemy-player and neutral colors preserve NPC colors");
        var copy=legacy.Copy();copy.EnemyPlayerColors.Medium="#FF7788";copy.NeutralPlayerColors.Name="#55AA77";copy.NeutralNpcColors.Medium="#5566AA";Check(legacy.Colors(1).Medium=="#EE1122"&&legacy.Colors(2).Name!="#55AA77"&&legacy.Colors(3).Medium=="#7799DD","Copied color presets must not share mutable values");
        var saved=EnemyHealthOptions.Read(json.Deserialize<Dictionary<string,object>>(json.Serialize(new{enemyHealth=legacy})));Check(saved.Colors(1).Medium=="#EE1122"&&saved.Colors(2).Value=="#12ABCD"&&saved.Colors(3).Medium=="#7799DD"&&saved.Bounds==original.Bounds,"Color-only presets persist without creating independent positions");saved.EnemyPlayerColors.Medium="invalid";saved.Normalize();Check(EnergyBarOptions.ValidColor(saved.Colors(1).Medium)&&saved.Colors(2).Value=="#12ABCD","Invalid preset color recovers independently");
        Directory.CreateDirectory(Path.Combine(root,"designs"));for(int kind=0;kind<4;kind++)using(var image=EnemyHealthOverlay.RenderPreview(480,.65,legacy,new BarDesign.GlowWorkspace(),"es",false,kind))image.Save(Path.Combine(root,"designs","our-target-palette-"+kind+".png"));
    }
    internal static void Run(string root){
        VerifyTextPresentation(root);VerifyPlayerTargets();VerifyTargetPalettes(root);VerifyTargetRelations();VerifyCacheIsolation();
        Check(EnemyNames.Name(2920619,"es")=="Atadura de Espinas de Vakron"&&EnemyNames.Name(2920618,"en")=="Vakron's Thorn Vines"&&EnemyNames.Name(2920364,"en")=="Gluttonous Tiere","Recorded expanded-range NPCs resolve from verified metadata in both languages");
        Check(EnemyNames.Name(2980240,"es")=="Sangre venenosa de Fafnir"&&EnemyNames.Name(2920655,"es")=="Enemigo","Existing local override is preserved and unnamed reference IDs remain unknown");

        EnemyHealthSignal.Sample special;var nightmare=Spawn(23146,1200000,1200000,2980240);Check(EnemyHealthSignal.Spawn(nightmare,0,nightmare.Length,out special)&&special.Npc==2980240&&special.Maximum==1200000,"Pesadilla NPC namespace retains explicit current/max instead of dropping valid special-instance enemies");var unsupported=Spawn(23146,10,10,3000000);Check(!EnemyHealthSignal.Spawn(unsupported,0,unsupported.Length,out special),"Expanded namespace still rejects unsupported identifiers");
        var signal=new EnemyHealthSignal();signal.Configure(true);Feed(signal,Energy(1923),100);Feed(signal,Spawn(34411),100);Feed(signal,Spawn(21922),100);
        Check(signal.Read()==null,"Spawn alone cannot choose an enemy");Feed(signal,Aim(1923,34411,15110340),101);Check(signal.Read().Actor==34411&&signal.Read().Maximum==119700,"Primary area aim selects explicit max");
        Feed(signal,Aim(1923,21922,15780007),101.1);Feed(signal,Aim(1923,1923,15760007),101.2);Feed(signal,Aim(1923,21922,15750007),101.3);Check(signal.Read().Actor==34411,"Procs, heals and retaliation cannot change primary target");
        Feed(signal,Hp(21922,85941),102);Feed(signal,Hp(34411,98460),102);Check(signal.Read().Current==98460,"Only tracked enemy HP shown");
        Feed(signal,Select(21922),103);Check(signal.Read().Actor==21922&&signal.Read().Locked,"Hard lock overrides soft target");Feed(signal,Aim(1923,34411,15110340),104);Check(signal.Read().Actor==21922,"Attacks do not override lock");Feed(signal,Hp(21922,0),105);Check(signal.Read()==null,"Locked target death hides without falling back to an old area target");
        Feed(signal,Select(34411),106);Check(signal.Read()!=null,"Tab can select existing NPC without attack");Feed(signal,Select(0),107);Check(signal.Read()==null,"Unlock clears old target");
        Feed(signal,Aim(1923,34411,15110340),108,"B");Feed(signal,Spawn(34411,1,10),108,"B");Check(signal.Read()==null,"Other flow cannot borrow self or target IDs");Feed(signal,Aim(1923,34411,15110340),109);Check(signal.Read().Maximum==119700,"Flow isolation");Check(EnemyHealthSignal.Fresh(signal.Read(),118)&&!EnemyHealthSignal.Fresh(signal.Read(),120),"Traffic freshness including clock skew");
        var serializer=new JavaScriptSerializer();var original=new EnemyHealthOptions();original.Bounds=new Rectangle(-400,180,360,6);original.Bar.MediumColor="#CC1122";var saved=EnemyHealthOptions.Read(serializer.Deserialize<Dictionary<string,object>>(serializer.Serialize(new{enemyHealth=original})));Check(saved.Bounds==original.Bounds&&saved.Bar.MediumColor==original.Bar.MediumColor&&!saved.Bar.AutoHide,"Persistence and no full-HP auto hide");var copy=saved.Copy();copy.Bar.TextSize=21;Check(saved.Bar.TextSize!=copy.Bar.TextSize,"Independent deep copy");copy.Name.FontSize=12;copy.Name.OffsetX=80;copy.Name.OffsetY=-180;copy.Name.Position=5;Check(saved.Name.FontSize==21&&saved.Name.OffsetX==-5,"Independent name deep copy");var titleBounds=EnemyNameOverlay.CaptionBounds(new Rectangle(100,200,420,6),copy.Name);Check(titleBounds.Y==34&&titleBounds.Width==430,"Free name offsets are not clipped to bar bounds");var nameSaved=EnemyHealthOptions.Read(serializer.Deserialize<Dictionary<string,object>>(serializer.Serialize(new{enemyHealth=copy})));Check(nameSaved.Name.FontSize==12&&nameSaved.Name.OffsetX==80&&nameSaved.Bar.TextSize==21,"Independent name persistence");using(var displaced=EnemyHealthOverlay.RenderPreview(420,.65,copy,new BarDesign.GlowWorkspace(),"es"))Check(displaced.Height>copy.Bounds.Height+87,"Preview must expand for displaced name");
        var rng=new Random(43);for(int i=0;i<3000;i++){var b=new byte[rng.Next(2,250)];rng.NextBytes(b);int[] ops={0x4136,0x4536,0x008d,0x3438,0x0238};int op=ops[i%ops.Length];b[0]=(byte)(op>>8);b[1]=(byte)op;Feed(signal,b,110+i*.0001);}signal.Reset();Check(signal.Read()==null,"Transport reset clears references");signal.Configure(false);Feed(signal,Energy(1923),200);Check(signal.Read()==null,"Disabled module ignores data");
        var workspace=new BarDesign.GlowWorkspace();using(var bitmap=EnemyHealthOverlay.RenderPreview(612,.738,new EnemyHealthOptions{Bounds=new Rectangle(0,0,612,8)},workspace,"es")){var path=Path.Combine(root,"designs");Directory.CreateDirectory(path);bitmap.Save(Path.Combine(path,"enemy-health-functional-preview.png"));}
        Check(EnemyNames.Name(2100752,"es")=="Karnif de la Meseta","Embedded localized name catalogue");using(var owner=new EnergyOverlay(root,true)){var settings=new HelperSettings(owner);try{settings.VerifyEnemyHealth(root);settings.VerifyEnemyTextOptions(root);}finally{settings.Close();}}
        File.WriteAllText(Path.Combine(root,"enemy-health-test.txt"),"PASS: PvP selected player explicit health/name, received rival focus and clears, no invented level/species; primary aim/area isolation; passive and self-heal exclusion; Tab/clear; actual HP/max; death; flow/freshness/reset; settings deep copy/persistence; configurable crisp black outlines, alpha/padding/pixel checks and independent metadata/lock-status controls; Tab-only visibility defaults and save/undo; malformed parser fuzz; embedded names and rendering; independent EN/ES settings and undo.");
    }
    static int DarkPixels(Bitmap image){int count=0;for(int y=0;y<image.Height;y++)for(int x=0;x<image.Width;x++){var p=image.GetPixel(x,y);if(p.A>0&&p.R<10&&p.G<10&&p.B<10)count++;}return count;}
    static Bitmap TextSample(CrispOverlayText text,int width,int opacity){var result=new Bitmap(250,70,System.Drawing.Imaging.PixelFormat.Format32bppPArgb);using(var g=Graphics.FromImage(result)){g.Clear(Color.Transparent);text.Draw(g,"45 · Feras  14 m",22,true,Color.White,new Rectangle(12,12,220,45),0,false,new TextOutlineOptions{Enabled=width>0,Width=Math.Max(1,width),Opacity=opacity});}return result;}
    static void VerifyTextPresentation(string root){
        var original=new EnemyHealthOptions();Check(!original.OnlyLocked&&!EnemyHealthOptions.TargetDefaults().OnlyLocked&&!original.Name.Outline.Enabled&&!original.Bar.TextOutline.Enabled,"Legacy appearance and unlocked target selection remain defaults");var sample=new EnemyHealthSignal.Sample{Distance=14};Check(EnemyHealthOverlay.SelectionAllowed(original,sample),"Ordinary attacks visible by default");original.OnlyLocked=true;Check(!EnemyHealthOverlay.SelectionAllowed(original,sample),"Lock-only mode hides ordinary attacks");sample.Locked=true;Check(EnemyHealthOverlay.SelectionAllowed(original,sample),"Tab target remains eligible even when it has metres");sample.Locked=false;Check(!EnemyHealthOverlay.SelectionAllowed(original,sample),"Unlock hides again");Check(EnemyHealthOverlay.LockCaption(true,"es")=="Bloqueado"&&EnemyHealthOverlay.LockCaption(false,"en")=="Unlocked","Independent lock status reports both states");
        original.Name.Outline.Enabled=true;original.Name.Outline.Width=3;original.Details.DistanceText.Outline.Enabled=true;original.Details.DistanceText.Outline.Opacity=45;original.Details.SpeciesText.Bold=true;original.LockText.Outline.Enabled=true;original.Bar.TextOutline.Enabled=true;var copy=original.Copy();copy.Name.Outline.Width=7;copy.Details.DistanceText.Outline.Opacity=10;copy.LockText.Outline.Enabled=false;copy.Bar.TextOutline.Enabled=false;Check(original.Name.Outline.Width==3&&original.Details.DistanceText.Outline.Opacity==45&&original.LockText.Outline.Enabled&&original.Bar.TextOutline.Enabled,"Text style snapshots cannot change another bar or undo state");var json=new JavaScriptSerializer();var saved=EnemyHealthOptions.Read(json.Deserialize<Dictionary<string,object>>(json.Serialize(new{enemyHealth=original})));Check(saved.OnlyLocked&&saved.Name.Outline.Width==3&&saved.Details.DistanceText.Outline.Opacity==45&&saved.LockText.Outline.Enabled&&saved.Bar.TextOutline.Enabled,"Selection and every text outline survive save/load");var invalid=new EnemyNameOptions{Outline=null};invalid.Normalize();invalid.Outline.Width=100;invalid.Outline.Opacity=-5;invalid.Normalize();Check(invalid.Outline.Width==8&&invalid.Outline.Opacity==0,"Malformed or legacy outline settings have bounded defaults");var core=new Rectangle(100,200,420,6);var plain=original.Name.Copy();plain.Outline.Enabled=false;var a=EnemyNameOverlay.CaptionBounds(core,plain);var b=EnemyNameOverlay.CaptionBounds(core,original.Name);Check(b.Contains(a)&&b.Width==a.Width+6&&b.Height==a.Height+6,"Text surfaces include the full outline without moving the text anchor");
        using(var renderer=new CrispOverlayText())using(var plainImage=TextSample(renderer,0,100))using(var thin=TextSample(renderer,1,100))using(var thick=TextSample(renderer,4,100))using(var faint=TextSample(renderer,4,25))using(var zero=TextSample(renderer,4,0)){
            Check(DarkPixels(thick)>DarkPixels(thin)&&DarkPixels(thin)>DarkPixels(plainImage),"Genuine glyph border expands with thickness");int maxFaint=0;for(int y=0;y<faint.Height;y++)for(int x=0;x<faint.Width;x++){var pixel=faint.GetPixel(x,y);if(pixel.R<10&&pixel.G<10&&pixel.B<10)maxFaint=Math.Max(maxFaint,pixel.A);}Check(maxFaint>0&&maxFaint<=64,"Outline opacity adjusts alpha without dimming glyphs");for(int y=0;y<zero.Height;y++)for(int x=0;x<zero.Width;x++)Check(zero.GetPixel(x,y)==plainImage.GetPixel(x,y),"Zero outline intensity preserves old text pixels");
            var folder=Path.Combine(root,"designs");Directory.CreateDirectory(folder);using(var compare=new Bitmap(760,150))using(var g=Graphics.FromImage(compare)){g.Clear(Color.FromArgb(219,215,196));g.DrawImageUnscaled(plainImage,0,10);g.DrawImageUnscaled(thin,250,10);g.DrawImageUnscaled(thick,500,10);compare.Save(Path.Combine(folder,"enemy-text-outline-comparison.png"));}
        }
    }
    internal static void Replay(string root,string frames){
        var json=new JavaScriptSerializer();string flow=null;double first=0;foreach(var line in File.ReadLines(frames)){var row=json.Deserialize<Dictionary<string,object>>(line);if(Convert.ToString(row["opcode"])!="0238")continue;string hex=Convert.ToString(row["hex"]);var b=Hex(hex);uint actor,target,skill;if(EnemyHealthSignal.Aim(b,0,b.Length,out actor,out target,out skill)&&actor==1923){flow=Convert.ToString(row["stream"]);first=Convert.ToDouble(row["ts"]);break;}}
        Check(flow!=null,"Replay must contain independently verified self1923 aim");double seed=first;foreach(var line in File.ReadLines(frames)){var row=json.Deserialize<Dictionary<string,object>>(line);if(Convert.ToString(row["stream"])==flow){seed=Convert.ToDouble(row["ts"]);break;}}var signal=new EnemyHealthSignal();signal.Configure(true);Feed(signal,Energy(1923),seed-.01,flow);int tab=0,clear=0,area=0;foreach(var line in File.ReadLines(frames)){var row=json.Deserialize<Dictionary<string,object>>(line);var b=Hex(Convert.ToString(row["hex"]));double t=Convert.ToDouble(row["ts"]);string key=Convert.ToString(row["stream"]);if(key==flow&&first-t>600)continue;Feed(signal,b,t,key);if(key!=flow)continue;int op=(b[0]<<8)|b[1];uint id,actor,target,skill;if(op==0x3438&&EnemyHealthSignal.Selection(b,0,b.Length,out id)){if(id==0){clear++;Check(signal.Read()==null,"Captured clear removes target");}else tab++;}if(op==0x0238&&EnemyHealthSignal.Aim(b,0,b.Length,out actor,out target,out skill)&&actor==1923&&target==34411&&skill==15110340){var sample=signal.Read();Check(sample!=null&&sample.Actor==34411&&sample.Maximum==119700,"Captured unlocked area cast selects principal NPC with observed max");area++;}}
        Check(tab>0&&clear>0&&area>0,"Replay requires actual Tab, clear and isolated area test");File.WriteAllText(Path.Combine(root,"enemy-health-replay-test.txt"),"PASS: PvP selected player explicit health/name, received rival focus and clears, no invented level/species; captured Tab and clear; unlocked Atadura invernal principal target34411/max119700; passive/HP/death handling. Self1923 supplied from independently verified research session identity.");
    }
    static byte[] Hex(string hex){var b=new byte[hex.Length/2];for(int i=0;i<b.Length;i++)b[i]=Convert.ToByte(hex.Substring(i*2,2),16);return b;}
}
